import unittest
from candidate import search

class TestSearch(unittest.TestCase):
    def test_search_normal_case(self):
        self.assertEqual(search([4, 1, 2, 2, 3, 1]), 2)

    def test_search_greatest_integer(self):
        self.assertEqual(search([1, 2, 2, 3, 3, 3, 4, 4, 4]), 3)

    def test_search_no_such_value(self):
        self.assertEqual(search([5, 5, 4, 4, 4]), -1)

    def test_search_single_element(self):
        self.assertEqual(search([1]), -1)

    def test_search_empty_list(self):
        with self.assertRaises(TypeError):
            search([])

    def test_search_non_positive_integer(self):
        with self.assertRaises(ValueError):
            search([-1, 0, 2, 3])

    def test_search_non_integer(self):
        with self.assertRaises(TypeError):
            search([1, 2, 'a', 4])

    def test_search_none_input(self):
        with self.assertRaises(TypeError):
            search(None)

if __name__ == '__main__':
    unittest.main()
